function deliveryAddressStreetKeyFinal_(value) {
  const s = deliveryNormalizeAddressForLocationMatchFinal_(value)
    .replace(/\b(?:unit|suite|apt|apartment)\s*[a-z0-9-]+\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const m = s.match(/^(\d+\s*[a-z]?)\s+(.+?)\s+(street|st|road|rd|drive|dr|avenue|ave|boulevard|blvd|lane|ln|court|ct|crescent|cres|way|trail|terrace|terr|place|pl)\b/i);
  if (!m) return '';

  const suffixMap = {
    street: 'st', st: 'st',
    road: 'rd', rd: 'rd',
    drive: 'dr', dr: 'dr',
    avenue: 'ave', ave: 'ave',
    boulevard: 'blvd', blvd: 'blvd',
    lane: 'ln', ln: 'ln',
