}

function deliveryFindCustomerNumberScopedLocationFinal_(locationIndex, customerNumber, addressValue) {
  const customerNo = deliveryPositiveIdOrBlank_(customerNumber);
  if (!customerNo || !locationIndex || !locationIndex.exists) {
    return { locationId: '', status: '', note: '' };
