  if (!candidates.length) {
    return {
      locationId: '',
      status: 'NO_CUSTOMER_NUMBER_LOCATION',
      note: 'No Striven Customer Location row was found for customer ' + customerNo + '.'
    };
  }

  if (candidates.length === 1) {
    return {
      locationId: candidates[0].locationId,
      status: 'MATCHED_CUSTOMER_NUMBER_UNIQUE_LOCATION',
      note: 'Customer ' + customerNo + ' has one unique Striven Location.'
    };
  }

  const addressKey = deliveryNormalizeAddressForLocationMatchFinal_(addressValue);
  if (addressKey) {
    const exact = candidates.filter(function(entry) {
      return entry.addressKey === addressKey;
    });
    if (exact.length === 1) {
      return {
        locationId: exact[0].locationId,
        status: 'MATCHED_CUSTOMER_NUMBER_EXACT_ADDRESS',
