      };
    }
  }

  const streetKey = deliveryAddressStreetKeyFinal_(addressValue);
  if (streetKey) {
    const street = candidates.filter(function(entry) {
      return entry.streetKey && entry.streetKey === streetKey;
    });
    if (street.length === 1) {
      return {
        locationId: street[0].locationId,
        status: 'MATCHED_CUSTOMER_NUMBER_STREET',
        note: 'Matched Location by customer number + street identity.'
      };
    }
  }

  const postalKey = deliveryAddressPostalKeyFinal_(addressValue);
  if (postalKey) {
    const postal = candidates.filter(function(entry) {
      return entry.postalKey && entry.postalKey === postalKey;
    });
    if (postal.length === 1) {
      return {
        locationId: postal[0].locationId,
        status: 'MATCHED_CUSTOMER_NUMBER_POSTAL',
        note: 'Matched Location by customer number + unique postal code.'
      };
    }
  }

