    locationId: '',
    status: 'MULTIPLE_CUSTOMER_LOCATIONS_NO_SAFE_ADDRESS_MATCH',
    note: 'Customer ' + customerNo + ' has multiple locations and Calendar/order address did not uniquely identify one.'
